\label{def:decay-function}
    A non-increasing function \(F\colon \intervalco{0,\infty} \to \intervaloo{0,\infty}\) is called a \emph{decay function} on \(\varGamma\) if
    \begin{align}
        \norm{F}
        &\coloneq
        \sup_{x\in \varGamma} \sum_{y \in \varGamma} F\pdist{x,y}
        <
        \infty
        \label{eq:F-norm}
    \shortintertext{and}
        C_F
        &\coloneq
        \sup_{x,y\in \varGamma} \sum_{z\in\varGamma} \frac{F\pdist{x,z} \, F\pdist{z,y}}{F\pdist{x,y}}
        <
        \infty
        \label{eq:convolution-constant}
        .
    \end{align}

\label{def:interaction}
    An \emph{interaction} is a map
    \begin{equation*}
        \varPhi\colon \mathcal{P}_0(\varGamma)\times I \to \mathcal{L}(\mathcal{A}), \ (Z,t) \mapsto \varPhi(Z,t)
        ,
    \end{equation*}
    such that the following conditions are satisfied:
    \begin{thmlist}
        \item
            \label{item:def-interaction:localized}
            \(\varPhi(Z,t)\in \mathcal{B}_Z\).
        \item
            \label{item:def-interaction:dissipative}
            \(\varPhi(Z,t)\) is dissipative 
            \footnote{ 
                An operator \(K\in \mathcal{L}(\mathcal{A})\) is called dissipative if for all \(\lambda>0\) and all \(A\in \mathcal{A}\) it holds that\\ \(\norm{(\lambda \, \operatorname{id} - K) \, A} \geq \lambda \, \norm{A}\).
                This is equivalent to \(\intervalco{0,\infty} \to \mathcal{L}(\mathcal{A}), \, t \mapsto {\mathrm{e}}^{tK}\) being a contraction semigroup by the Lumer-Phillips Theorem.
            } 
            .
        \item
            \label{item:def-interaction:continuous}
            For all \(Z\in \mathcal{P}_0(\varGamma)\) the map \(I \to \mathcal{L}(\mathcal{A}),\ t \mapsto \varPhi(Z,t)\) is norm-continuous and uniformly bounded.
    \end{thmlist}

    \noindent
    We call \(\varPhi\) \emph{finitely supported} if \(\sup_{t\in I} \, \norm{\varPhi(Z,t)} = 0\) for all but finitely many \(Z\in \mathcal{P}_0(\varGamma)\).
    We say it has \emph{finite range}~\(R\geq 0\) if \(\sup_{t\in I} \, \norm{\varPhi(Z,t)} = 0\) unless \(\diam{Z} \leq R\), and it is a \emph{\(k\)-body} interaction for some \(k\in\mathbb{N}_{>0}\) if \(\sup_{t\in I} \, \norm{\varPhi(Z,t)} = 0\) unless \(\abs{Z} \leq k\).

    \noindent
    To control the total interaction strength at each site, we set
    \begin{equation}
        \label{eq:def-interaction-1-norm}

        \IfBooleanTF{\varPhi}{
        \MT_delim_tnorm_star_wrapper:nnn 
            {\bgroup\left|\mkern-1.5mu\bgroup\left|\mkern-1.5mu\bgroup\left|}{#3}{\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|}             
        }{
            \IfValueTF{_}{
                \@nameuse{MT_delim_tnorm_nostarscaled_wrapper:nnn} 
                    {\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|}
                    {#3}
                    {\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|}
            }{
                \MT_delim_tnorm_nostarnonscaled_wrapper:nnn 
                    {|\mkern-1.5mu|\mkern-1.5mu|}
                    {#3}
                    {|\mkern-1.5mu|\mkern-1.5mu|}
            }
        }
    1
        \coloneq
        \sup_{u\in I} \, \sup_{x\in \varGamma} \, \ifstrempty{r}{\sum_{\substack{Z\in \mathcal{P}_0(\varGamma)\mathpunct{\ordinarycolon}\\ x\in Z}}}{\smashoperator[r]{\sum_{\substack{Z\in \mathcal{P}_0(\varGamma)\mathpunct{\ordinarycolon}\\ x\in Z}}}} \, \norm{\varPhi(Z,u)}
        .
    \end{equation}

    \noindent
    For a decay function~\(F\) on \(\varGamma\), we define the \emph{interaction norm}
    \begin{equation}
        \label{eq:interaction-norm}
        \norm{\varPhi(t)}_F
        \coloneq
        \sup_{x,y \in \varGamma}
        \ifstrempty{}{\sum_{\substack{Z\in \mathcal{P}_0(\varGamma)\\ x,y\in Z}}}{\smashoperator[]{\sum_{\substack{Z\in \mathcal{P}_0(\varGamma)\\ x,y\in Z}}}}
        \frac{\norm{\varPhi(Z,t)}}{F\pdist{x,y}}
        ,
    \end{equation}
    and say that~\(\varPhi\) has \emph{\(F\)-decay} if
    \begin{equation*}

        \IfBooleanTF{\varPhi}{
        \MT_delim_tnorm_star_wrapper:nnn 
            {\bgroup\left|\mkern-1.5mu\bgroup\left|\mkern-1.5mu\bgroup\left|}{#3}{\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|}             
        }{
