                    {\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|}
                    {#3}
                    {\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|}
            }{
                \MT_delim_tnorm_nostarnonscaled_wrapper:nnn 
                    {|\mkern-1.5mu|\mkern-1.5mu|}
