        \coloneq
        \sup_{t\in I} \, \norm{\varPhi(t)}_F
        <
        \infty
        .
    \end{equation*}

\label{def:time-evolution-finitely-supported-case}
    Let \(\varPhi\) be a finitely supported interaction.
    The \emph{time evolution generated by \(\varPhi\)} is the map
    \begin{equation*}
        \tau\colon \varDelta_I^2 \to \mathcal{L}(\mathcal{A}), \, (s,t) \mapsto \tau_{s,t}
    \end{equation*}
    defined by the time-ordered exponential
    \begin{equation}
        \label{eq:def-time-evolution-finitely-supported-case}
        \tau_{s,t}
        \coloneq
        \sum_{n=0}^\infty

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{r}{\sum_{\substack{Z_1\in \mathcal{P}_0(\varGamma)}}}{\smashoperator[r]{\sum_{\substack{Z_1\in \mathcal{P}_0(\varGamma)}}}}
        \, \varPhi(Z_1,u_1)
        \, \dotsm
        \, \ifstrempty{lr}{\sum_{\substack{Z_n\in \mathcal{P}_0(\varGamma)}}}{\smashoperator[lr]{\sum_{\substack{Z_n\in \mathcal{P}_0(\varGamma)}}}}
        \, \varPhi(Z_n,u_n)
        ,
    \end{equation}
    where the \(n=0\) term is defined to be \(\operatorname{id}_{\mathcal{A}}\), the identity map on \(\mathcal{A}\).

\label{prop:finite-evolutions}
    Let \(\varPhi\) be a finitely supported interaction and let \(\tau\) be its generated evolution.
    It holds that
    \begin{thmlist}
        \item
            \label{item:prop-finite-evolutions:cocycle}
            \(\tau_{s,t} \, \tau_{t,u} = \tau_{s,u}\) for all \((s,t,u) \in \varDelta^3_I\),
        \item
            \label{item:prop-finite-evolutions:identity}
            \(\tau_{s,s} = \operatorname{id}\) for all \(s \in I\),
        \item
            \label{item:prop-finite-evolutions:continuity}
            \(\tau\) is norm-continuous in both arguments,
        \item
            \label{item:prop-finite-evolutions:derivative-second}
            \(\tau\) is norm-differentiable in the second argument and\newline \(
                \partial_{t} \, \tau_{s,t}
                =
                \sum_{Z\in \mathcal{P}_0(\varGamma)} \tau_{s,t} \, \varPhi(Z,t)\;
            \) for all \((s,t)\in \varDelta^2_I\),
        \item
            \label{item:prop-finite-evolutions:derivative-first}
            \(\tau\) is norm-differentiable in the first argument and\newline \(
                \partial_{s} \, \tau_{s,t}
                =
                -\sum_{Z\in \mathcal{P}_0(\varGamma)} \varPhi(Z,s) \, \tau_{s,t}\;
            \) for all \((s,t)\in \varDelta^2_I\),
        \item
            \label{item:prop-finite-evolutions:contractive}
            \(\norm{\tau_{s,t}} \leq 1\) for all \((s,t)\in \varDelta^2_I\).
    \end{thmlist}

\label{thm:adaptive-dyson-expansion}
    Let \(\varPhi\) be an interaction satisfying
    \begin{equation}
        \label{eq:weighted-interaction-summability}
        C_\varPhi
        \coloneq
        \sup_{t\in I} \, \sup_{x\in\varGamma}
        \, \ifstrempty{r}{\sum_{\substack{Z\in\mathcal{P}_0(\varGamma)\\ x\in Z}}}{\smashoperator[r]{\sum_{\substack{Z\in\mathcal{P}_0(\varGamma)\\ x\in Z}}}}
        \, \abs{Z} \, \norm{\varPhi(Z,t)}
        <
        \infty
        .
    \end{equation}
    Then \(\varPhi\) generates a time evolution~\(\tau\) in the sense of \cref{def:time-evolution-general-case}.
    For every self-avoiding path \(\eta \in\mathrm{SP}\), the interaction
    \begin{equation}
        \label{eq:thm-path-dependent-interactions}
        \varPhi^{\eta}(Z,u)
        \coloneq
        \begin{cases*}
            \varPhi(Z,u) & if \(\eta \perp Z\)
            \\
            0         & otherwise
        \end{cases*}
    \end{equation}
    also generates a time evolution, denoted by~\(\tau^{\eta}\).

    For all \(s\),~\(t \in I\) with \(s \leq t\), \(X\),~\(Y\in \mathcal{P}_0(\varGamma)\), \(K \in \mathcal{B}_X\) and \(B\in \mathcal{A}_Y\), we have the following absolutely convergent expansion
    \begin{equation}
        \label{eq:thm-adaptive-dyson-expansion}
        K \, \tau_{s,t} \, B
        =
        K
        \, \sum_{n=0}^\infty
        \, 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{r}{\sum_{\substack{\gamma\in \mathrm{SP}_n(X,Y)}}}{\smashoperator[r]{\sum_{\substack{\gamma\in \mathrm{SP}_n(X,Y)}}}}
        \,
        \begin{aligned}[t]
            \tau_{s,u_1}
            \, \varPhi(\gamma_1,u_1)
            & \, \tau^{\gamma_{:0}}_{u_1,u_2}
            \, \varPhi(\gamma_2,u_2)
            \\&\dotsm
            \, \tau^{\gamma_{:n-2}}_{u_{n-1},u_n}
            \, \varPhi(\gamma_{n},u_n)
            \, \tau^{\gamma_{:n-1}}_{u_n,t}
            \, B
            ,
        \end{aligned}
    \end{equation}
    where the \(n=0\) term is defined to be \(K \, \sum_{\gamma\in \mathrm{SP}_0(X,Y)} \, \tau_{s,t} \, B\).

    Furthermore, if \(X\) and \(Y\) are disjoint, then
    \begin{equation}
        \label{eq:thm-adaptive-dyson-expansion-norm-bound}
        \norm{K \, \tau_{s,t} \, B}
        \leq
        \norm{K} \, \norm{B}
        \, \sum_{n=1}^{\infty}
        \, \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{SP}_n(X,Y)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{SP}_n(X,Y)}}}}
        \, 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(\gamma_j,u_j)}
        .
    \end{equation}

\label{cor:Lieb-Robinson-bound-nearest-neighbour-spin-chain}
    Suppose \(\varGamma=\mathbb{Z}\) with the \(\ell^1\)-distance.
    Let \(\varPhi\) be a nearest-neighbour interaction, i.e.\ \(\varPhi(Z,u)=0\) unless \(\diam{Z} \leq 1\), and assume that \({
        \IfBooleanTF{\varPhi}{
        \MT_delim_tnorm_star_wrapper:nnn 
            {\bgroup\left|\mkern-1.5mu\bgroup\left|\mkern-1.5mu\bgroup\left|}{#3}{\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|}             
        }{
            \IfValueTF{_}{
                \@nameuse{MT_delim_tnorm_nostarscaled_wrapper:nnn} 
                    {\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|}
                    {#3}
                    {\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|}
            }{
                \MT_delim_tnorm_nostarnonscaled_wrapper:nnn 
                    {|\mkern-1.5mu|\mkern-1.5mu|}
                    {#3}
                    {|\mkern-1.5mu|\mkern-1.5mu|}
            }
        }
    1 < \infty}\).
    Then \(\varPhi\) generates a time evolution~\(\tau\).

    For non-empty finite sets \(X\),~\(Y\subseteq\mathbb{Z}\), write \(X<Y\) if \(\max X<\min Y\).
    For all such \(X\),~\(Y\) with \(X<Y\) or \(Y<X\), all \(s\),~\(t\in I\) with \(s\leq t\), \(K\in\mathcal{B}_X\), and \(B\in\mathcal{A}_Y\), it holds that
    \begin{equation*}
        \norm{K \, \tau_{s,t} \, B}
        \leq
        \norm{K}
        \, \norm{B}
        \, \frac{
            \paren[\big]{
                J \, (t-s)
            }^{\dist{X,Y}}
        }{
            \dist{X,Y}!
        }
        ,
    \end{equation*}
    where \(
        J \coloneq \sup_{u\in \intervalcc{s,t}}
        \, \sup_{z\in \varLambda}
        \, \norm[\big]{\varPhi(\List{z,z+1}, u)}
    \) and
    \begin{equation*}
        \varLambda
        =
        \text{\small\(\displaystyle
                \begin{cases*}
                    \List{\max X, \max X + 1, \dotsc, \min Y -1}
                     & if \(X<Y\),
                    \\
                    \List{\max Y, \max Y + 1, \dotsc, \min X -1}
                     & if \(Y<X\).
                \end{cases*}
            \)}
    \end{equation*}

\label{thm:Lieb-Robinson-bound}
    Let \(F\) be a decay function on \(\varGamma\), and let \(\varPhi\) be an interaction with \(F\)-decay.
    Let \(\tau\) be its generated evolution.
    For all \(s\),~\(t\in I\) with \(s\leq t\), disjoint \(X\),~\(Y\in\mathcal{P}_0(\varGamma)\), \(K\in\mathcal{B}_X\), and \(B\in\mathcal{A}_Y\), it holds that
    \begin{equation}
        \label{eq:thm-Lieb-Robinson-bound}
        \norm{K \, \tau_{s,t} \, B}
        \leq
        \norm{K} \, \norm{B} \, C_F^{-1}
        \, \paren[\big]{{\mathrm{e}}^{C_F \, I_{\tilde{\varPhi}}(s,t)}-1}
        \, \sum_{x\in X} \, \sum_{y\in Y} \, F\pdist{x,y}
        .
    \end{equation}

\label{rem:square-lattice-Lieb-Robinson-bound}
    Consider again \(\varGamma = \mathbb{Z}^D\) equipped with the \(\ell^1\)-distance, and fix \(\alpha > D\).
    We use the decay functions introduced in \cref{rem:square-lattice-decay-function}.
    There exists a constant \(C\) such that
    \begin{equation}
        \label{eq:rem-tail-sum-on-square-lattice}
        \ifstrempty{r}{\sum_{\substack{
            y\in \varGamma \mathpunct{\ordinarycolon}\\
            \dist{x,y} \geq r
        }}}{\smashoperator[r]{\sum_{\substack{
            y\in \varGamma \mathpunct{\ordinarycolon}\\
            \dist{x,y} \geq r
        }}}} \, F_\alpha\pdist{x,y}
        \leq
        C \, F_{\alpha-D}(r)
        ,
    \end{equation}
    for all \(x\in \varGamma\) and \(r \geq 0\).
    Hence, the double sum in~\eqref{eq:thm-Lieb-Robinson-bound} is bounded as
    \begin{equation*}
        \sum_{x\in X} \, \sum_{y\in Y} \, F_\alpha\pdist{x,y}
        \leq
        C \, \min\List{\abs{X},\abs{Y}} \, F_{\alpha-D} \pdist{X,Y}
    \end{equation*}
    by applying~\eqref{eq:rem-tail-sum-on-square-lattice} to either of the sums.

    For the exponential decay \(F(r) = F_\alpha(r) \, {\mathrm{e}}^{-b r}\) the same argument produces an additional factor \({\mathrm{e}}^{-b \, \dist{X,Y}}\), so that~\eqref{eq:thm-Lieb-Robinson-bound} gives
    \begin{equation*}
        \norm{K \, \tau_{s,t} \, B}
        \leq
        \norm{K} \, \norm{B} \, C \, C_F^{-1} \, \min\List{\abs{X},\abs{Y}} \, {\mathrm{e}}^{b \, \paren*{\xmathstrut{.1}v \, (t-s) - \dist{X,Y}}}
        ,
    \end{equation*}
    which resembles the form~\eqref{eq:LRB-short-range-intro} with velocity \(v = C_F \, 
        \IfBooleanTF{\tilde{\varPhi}}{
        \MT_delim_tnorm_star_wrapper:nnn 
            {\bgroup\left|\mkern-1.5mu\bgroup\left|\mkern-1.5mu\bgroup\left|}{#3}{\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|}             
        }{
            \IfValueTF{_}{
                \@nameuse{MT_delim_tnorm_nostarscaled_wrapper:nnn} 
                    {\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|}
                    {#3}
                    {\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|}
            }{
