                    {|\mkern-1.5mu|\mkern-1.5mu|}
                    {#3}
                    {|\mkern-1.5mu|\mkern-1.5mu|}
            }
        }
    1\) and \(\tilde{\varPhi}\) is defined in~\eqref{eq:thm-interaction-without-on-site-terms}.

For \(\varGamma=\mathbb{Z}^D\) with the \(\ell^p\) distance, \(1\leq p\leq\infty\), every set of diameter at most \(R\in \mathbb{N}_{>0}\) fits into a cube of side length \(R\), containing at most \((R+1)^D\) lattice points.
    Thus, for an interaction of range \(R\), one may always take \(k=(R+1)^D\).
    Moreover,
    \begin{equation*}

        \IfBooleanTF{\varPhi}{
        \MT_delim_tnorm_star_wrapper:nnn 
            {\bgroup\left|\mkern-1.5mu\bgroup\left|\mkern-1.5mu\bgroup\left|}{#3}{\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|}             
        }{
            \IfValueTF{_}{
                \@nameuse{MT_delim_tnorm_nostarscaled_wrapper:nnn} 
                    {\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|}
                    {#3}
                    {\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|}
            }{
                \MT_delim_tnorm_nostarnonscaled_wrapper:nnn 
                    {|\mkern-1.5mu|\mkern-1.5mu|}
                    {#3}
                    {|\mkern-1.5mu|\mkern-1.5mu|}
            }
        }
    1
        \leq
        \sum_{j=1}^k
        \, \binom{(2R+1)^D}{j}
        \, \sup_{u\in I}
        \, \sup_{Z\in\mathcal{P}_0(\varGamma)}
        \, \norm{\varPhi(Z,u)}
        ,
    \end{equation*}
    since every contributing set \(Z\ni x\) is contained in the ball of radius \(R\) around \(x\), which contains at most \((2R+1)^D\) lattice points.

\label{cor:localization-of-operators}
    Let \(F\) be a decay function on \(\varGamma\), and let \(\varPhi\) be an interaction with \(F\)-decay.
    Let \(\tau\) be its generated evolution.
    For all \(s\),~\(t \in I\) with \(s \leq t\), \(Y\in \mathcal{P}_0(\varGamma)\), \(B\in \mathcal{A}_Y\), \(r\geq 0\), there exists an approximation \(B_r\in \mathcal{A}_{Y[r]}\) such that
    \begin{equation*}
        \norm{
