Fix \((s,t)\in\varDelta_I^2\).
    First let \(B\in \mathcal{A}_Y\) with \(Y\in \mathcal{P}_0(\varGamma)\).
    We show that the net \((\tau_{s,t}^\varLambda \, B)_{\varLambda \in \mathcal{P}_0(\varGamma)}\) is Cauchy.

    Let \(\varLambda\in\mathcal{P}_0(\varGamma)\) contain \(Y\), and let \(\varLambda_1\),~\(\varLambda_2\in\mathcal{P}_0(\varGamma)\) contain \(\varLambda\).
    Duhamel's formula gives
    \begin{equation*}
        \paren[\big]{\tau_{s,t}^{\varLambda_1}-\tau_{s,t}^{\varLambda_2}} \, B
        =

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_s^t \odif{u}
        \, \tau_{s,u}^{\varLambda_1}
        \, \paren[\bigg]{
            \ifstrempty{}{\sum_{\substack{Z \subseteq \varLambda_1}}}{\smashoperator[]{\sum_{\substack{Z \subseteq \varLambda_1}}}} \varPhi(Z,u)
            - \ifstrempty{}{\sum_{\substack{Z \subseteq \varLambda_2}}}{\smashoperator[]{\sum_{\substack{Z \subseteq \varLambda_2}}}} \varPhi(Z,u)
        }
        \, \tau_{u,t}^{\varLambda_2} \, B
        .
    \end{equation*}
    Every term with \(Z\subseteq \varLambda_1\cap \varLambda_2\) occurs in both sums and cancels, all others satisfy \(Z \not\subseteq \varLambda\).
    Thus, taking norms, using Tonelli and \cref{eq:thm-adaptive-dyson-expansion-norm-bound} for the finitely supported~\(\varPhi\rvert_{\varLambda_2}\) to bound \(\norm{\varPhi(Z,u) \, \tau_{u,t}^{\varLambda_2} \, B}\), and enlarging the sum over self-avoiding paths to paths yields
    \begin{align}
        \notag
        \norm[\big]{\paren[\big]{\tau_{s,t}^{\varLambda_1}-\tau_{s,t}^{\varLambda_2}} \, B}
        &\leq
        \, \ifstrempty{lr}{\sum_{\substack{
            Z\in\mathcal{P}_0(\varGamma)\\
            Z\not\subseteq\varLambda
        }}}{\smashoperator[lr]{\sum_{\substack{
            Z\in\mathcal{P}_0(\varGamma)\\
            Z\not\subseteq\varLambda
        }}}}\quad

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_s^t \odif{u}
        \, \norm[\big]{\varPhi(Z,u) \, \tau_{u,t}^{\varLambda_2} \, B}
        \\&\leq
        \label{eq:proof-TDL-expansion}
        \norm{B}
        \, \ifstrempty{lr}{\sum_{\substack{
            Z\in\mathcal{P}_0(\varGamma)\\
            Z\not\subseteq\varLambda
        }}}{\smashoperator[lr]{\sum_{\substack{
            Z\in\mathcal{P}_0(\varGamma)\\
            Z\not\subseteq\varLambda
        }}}}
        \quad 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_s^t \odif{u}
        \, \norm{\varPhi(Z,u)}
        \, \sum_{n=0}^\infty
        \, 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{u,t}} \odif{v}
        \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(Z,Y)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(Z,Y)}}}}
        \, \prod_{j=1}^n \, \norm{\varPhi(\gamma_j,v_j)}
        .
    \end{align}
    The bound is independent of \(\varLambda_1\) and \(\varLambda_2\).
    Moreover, the outer sum on the right-hand side of~\eqref{eq:proof-TDL-expansion} without the condition \(Z\not\subseteq\varLambda\) converges absolutely.
    To see this, consider the bijection
    \begin{align*}
        \mathrm{P}_{n+1}(Y)
        &\to
        \Set{ (Z,\gamma)  

    \nonscript\,\delimsize\vert
    \allowbreak
    \nonscript\,
    \mathopen{} Z \in \mathcal{P}_0(\varGamma),\ \gamma\in \mathrm{P}_n(Z,Y)}
        \\
        \eta
        &\mapsto
        \paren[\big]{
            \eta_{n+1},
            (\eta_{n+1}, \eta_n, \dotsc, \eta_{1}, \eta_{0} = Y)
        }
        .
    \end{align*}
    Therefore, after using Tonelli’s theorem, \cref{lem:summability-of-path-weights} and  \(
        \int_s^t \odif{u} \int_{\varDelta^n_{u,t}} \odif{v}
        =
        \int_{\varDelta^{n+1}_{s,t}} \odif{v}
    \), we can upper bound
    \begin{align*}
        \hspace*{2em}&\hspace*{-2em}
        \norm{B}
        \, \ifstrempty{lr}{\sum_{\substack{
            Z\in\mathcal{P}_0(\varGamma)
        }}}{\smashoperator[lr]{\sum_{\substack{
            Z\in\mathcal{P}_0(\varGamma)
        }}}}
        \quad 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_s^t \odif{u}
        \, \norm{\varPhi(Z,u)}
        \, \sum_{n=0}^\infty
        \, 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{u,t}} \odif{v}
        \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(Z,Y)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(Z,Y)}}}}
        \, \prod_{j=1}^n \, \norm{\varPhi(\gamma_j,v_j)}\\
        &\leq
        \norm{B}
        \, \sum_{n=0}^\infty
        \, 
    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_s^t \odif{u}

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{u,t}} \odif{v}
        \ifstrempty{r}{\sum_{\substack{\eta\in\mathrm{P}_{n+1}(Y)}}}{\smashoperator[r]{\sum_{\substack{\eta\in\mathrm{P}_{n+1}(Y)}}}}
        \, \norm{\varPhi(\eta_{n+1},u)}
        \, \prod_{j=1}^n \, \norm{\varPhi(\eta_j,v_{n+1-j})}
        \\&\leq
        \norm{B}
        \, \sum_{n=0}^\infty
        \, \frac{(t-s)^{n+1}}{(n+1)!}
        \, \abs{Y}
        \, 
        \IfBooleanTF{\varPhi}{
        \MT_delim_tnorm_star_wrapper:nnn 
            {\bgroup\left|\mkern-1.5mu\bgroup\left|\mkern-1.5mu\bgroup\left|}{#3}{\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|\mkern-1.5mu\aftergroup\egroup\right|}             
        }{
            \IfValueTF{_}{
                \@nameuse{MT_delim_tnorm_nostarscaled_wrapper:nnn} 
                    {\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ l}|}
                    {#3}
                    {\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|\mkern-1.5mu\@nameuse {\MH_cs_to_str:N _ r}|}
            }{
