        }
    1
        \, C_\varPhi^{n}
        \\&\leq
        \norm{B}
        \, \abs{Y}
        \, {\mathrm{e}}^{C_\varPhi \, (t-s)}
        .
    \end{align*}

    This, together with the fact that each finite set \(Z\) is eventually contained in \(\varLambda\) as~\(\varLambda\nearrow\varGamma\), implies that the right-hand side of~\eqref{eq:proof-TDL-expansion} tends to zero as \(\varLambda\nearrow\varGamma\).
    Since \(\varLambda\subseteq \varLambda_1,\varLambda_2\), this implies \(
        \norm[\big]{\paren[\big]{\tau_{s,t}^{\varLambda_1}-\tau_{s,t}^{\varLambda_2}} \, B} \to 0
    \) as \(\varLambda_1\),~\(\varLambda_2 \nearrow \varGamma\). 

    Now let \(B\in \mathcal{A}\), and let \((B_n)_{n\in \mathbb{N}_0}\) be a sequence of operators supported on finite sets approximating~\(B\).
    We find for all \(n\in \mathbb{N}_0\) that
    \begin{align*}
        \norm{\tau_{s,t}^{\varLambda_1} \, B - \tau_{s,t}^{\varLambda_2} \, B}
        &\leq
        \norm{\tau_{s,t}^{\varLambda_1} \, B - \tau_{s,t}^{\varLambda_1} \, B_n}
        +
        \norm{\tau_{s,t}^{\varLambda_1} \, B_n - \tau_{s,t}^{\varLambda_2} \, B_n}
        +
        \norm{\tau_{s,t}^{\varLambda_2} \, B_n - \tau_{s,t}^{\varLambda_2} \, B}
        \\&\leq
        \norm{B-B_n}
        +
        \norm{\tau_{s,t}^{\varLambda_1} \, B_n - \tau_{s,t}^{\varLambda_2} \, B_n}
        +
        \norm{B_n - B}
        .
    \end{align*}
    Choosing first \(n\) and then \(\varLambda_1\),~\(\varLambda_2\) sufficiently large shows that the net is Cauchy and thus converges in norm.

\label{lem:bounding-sum-over-n-long-paths}
    Let \(F\) be a decay function on \(\varGamma\), and let \(\varPhi\) be an interaction with \(F\)-decay.
    Fix \((s,t)\in \varDelta^2_I\).
    For all \(X\),~\(Y\in \mathcal{P}_0(\varGamma)\) and \(n\in \mathbb{N}_{>0}\), it holds that
    \begin{align}
        \label{eq:lem-bounding-sum-over-n-long-paths-from-X-to-Y}

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(X,Y)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(X,Y)}}}}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(\gamma_j,u_j)}
        &\leq
        \sum_{x\in X} \, \sum_{y\in Y} \, F\pdist{x,y}
        \, \frac{C_F^{n-1} \, I_{\varPhi}(s,t)^n}{n!}
    \shortintertext{and}
        \label{eq:lem-bounding-sum-over-n-long-paths-attached-to-X}

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(X)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(X)}}}}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(\gamma_j,u_j)}
        &\leq
        \abs{X} \, \norm{F}
        \, \frac{C_F^{n-1} \, I_{\varPhi}(s,t)^n}{n!}
        .
    \end{align}
    For \(n=0\), the left-hand side of~\eqref{eq:lem-bounding-sum-over-n-long-paths-from-X-to-Y} equals \(1\) if \(X\cap Y\neq\emptyset\) and \(0\) otherwise, while that of~\eqref{eq:lem-bounding-sum-over-n-long-paths-attached-to-X} equals \(1\).

For \(n=0\), there is exactly one path in \(\mathrm{P}_0(X)\), namely \((X)\).
    On the other hand, \(\mathrm{P}_0(X,Y)\) consists of \((X,Y)\) if \(X\cap Y\neq\emptyset\) and is empty otherwise.
    The claimed values follow, since the empty product and the integral over \(\varDelta^0_{s,t}\) equal \(1\).
    Therefore, in the remainder of the proof we assume \(n\in\mathbb{N}_{>0}\).

    For every path \(\gamma\), we can find a point in each intersection \(z_j\in \gamma_{j-1} \cap \gamma_{j}\).
    Hence, we can upper bound the sum over paths~\eqref{eq:lem-bounding-sum-over-n-long-paths-from-X-to-Y} as
    \begin{align*}

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(X,Y)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(X,Y)}}}}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(\gamma_j,u_j)}
        &\leq

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{l}{\sum_{\substack{
            z_1\in X\\
            z_2,\dotsc,z_{n} \in\varGamma\\
            z_{n+1} \in Y
        }}}{\smashoperator[l]{\sum_{\substack{
            z_1\in X\\
            z_2,\dotsc,z_{n} \in\varGamma\\
            z_{n+1} \in Y
        }}}}
        \, \prod_{j=1}^n
        \, \ifstrempty{r}{\sum_{\substack{
            \gamma_j\in \mathcal{P}_0(\varGamma)\mathpunct{\ordinarycolon}\\
            z_j,z_{j+1} \in \gamma_j
        }}}{\smashoperator[r]{\sum_{\substack{
            \gamma_j\in \mathcal{P}_0(\varGamma)\mathpunct{\ordinarycolon}\\
            z_j,z_{j+1} \in \gamma_j
        }}}}
        \, \norm{\varPhi(\gamma_j,u_j)}
        \\&\leq

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{l}{\sum_{\substack{
            z_1\in X\\
            z_2,\dotsc,z_{n} \in\varGamma\\
            z_{n+1} \in Y
        }}}{\smashoperator[l]{\sum_{\substack{
            z_1\in X\\
            z_2,\dotsc,z_{n} \in\varGamma\\
            z_{n+1} \in Y
        }}}}
        \, \prod_{j=1}^n
        \, F\pdist{z_j,z_{j+1}}
        \, \norm{\varPhi(u_j)}_F
        \\&\leq

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{lr}{\sum_{\substack{
            z_1\in X\\
            z_{n+1} \in Y
        }}}{\smashoperator[lr]{\sum_{\substack{
            z_1\in X\\
            z_{n+1} \in Y
        }}}}
        \, C_F^{n-1}
        \, F\pdist{z_1,z_{n+1}}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(u_j)}_F
        \\&=
        \ifstrempty{lr}{\sum_{\substack{
            z_1\in X\\
            z_{n+1} \in Y
        }}}{\smashoperator[lr]{\sum_{\substack{
            z_1\in X\\
            z_{n+1} \in Y
        }}}}
        \, C_F^{n-1}
        \, F\pdist{z_1,z_{n+1}}
        \, \frac{1}{n!}
        \, \paren[\bigg]{\int_s^t \odif{u} \, \norm{\varPhi(u)}_F}^n
        ,
    \end{align*}
    where we used the definition~\eqref{eq:interaction-norm} of the interaction norm in the second step, the convolution property~\eqref{eq:convolution-constant} \(n-1\) times in the third step, and the symmetry of the integrand under permutations of the time variables in the last step.

    To obtain~\eqref{eq:lem-bounding-sum-over-n-long-paths-attached-to-X}, notice that every path \(\gamma\in \mathrm{P}_n(X)\) has a final non-empty set containing a point \(y\in \varGamma\).
    Therefore, by overcounting
    \begin{align*}

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(X)}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(X)}}}}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(\gamma_j,u_j)}
        &\leq

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \sum_{y\in \varGamma}
        \, \ifstrempty{}{\sum_{\substack{\gamma\in\mathrm{P}_n(X,\List{y})}}}{\smashoperator[]{\sum_{\substack{\gamma\in\mathrm{P}_n(X,\List{y})}}}}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(\gamma_j,u_j)}
        \\&\leq

    \int_{\mathrlap{#1}}^{\mathrlap{#2}}
_{\varDelta^n_{s,t}} \odif{u}
        \, \sum_{x\in X} \, \sum_{y\in \varGamma}
        \, C_F^{n-1}
        \, F\pdist{x,y}
        \, \prod_{j=1}^n
        \, \norm{\varPhi(u_j)}_F
        \\&\leq
        \abs{X} \, \norm{F}
        \, \frac{C_F^{n-1} \, I_{\varPhi}(s,t)^n}{n!}
        ,
    \end{align*}
    where we used the bound on the integrand from the first three steps of the previous estimate, applied with \(Y=\List{y}\), in the second step.
    This concludes the proof.

